  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, status, attribution_type, created_by, updated_by)
  VALUES
    (v_a1, 'TUT-KOMPUTER8-001', 'baaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Canva untuk Pemula: Desain Grafis Tanpa Ribet', 'canva-untuk-pemula-desain-grafis', 'Panduan lengkap memakai Canva untuk membuat poster, presentasi, dan konten media sosial yang menarik tanpa keahlian desain.', 'id', 6, 'Madevi', v_owner, 'MEMBER', 'DRAFT', 'DEVELOPED_BY', v_owner, v_owner),
    (v_a2, 'TUT-KESEHATAN11-001', 'b5555555-5555-5555-5555-555555555555', 'Tekanan Darah Tinggi: Ubah Gaya Hidup, Turunkan Risiko', 'tekanan-darah-tinggi-gaya-hidup', 'Informasi umum tentang hipertensi dan langkah gaya hidup yang membantu mengendalikannya, plus kapan harus ke dokter.', 'id', 6, 'Madevi', v_owner, 'MEMBER', 'DRAFT', 'DEVELOPED_BY', v_owner, v_owner),
    (v_a3, 'EXP-ANTROPOLOGI7-001', 'c8888888-8888-8888-8888-888888888888', 'Suku Batak: Dalihan Na Tolu dan Kekuatan Kekerabatan', 'suku-batak-dalihan-na-tolu', 'Mengenal masyarakat Batak: falsafah Dalihan Na Tolu, marga, adat, dan warisan budayanya di Nusantara.', 'id', 5, 'Madevi', v_owner, 'MEMBER', 'DRAFT', 'DEVELOPED_BY', v_owner, v_owner),
    (v_a4, 'EXP-FISIKA10-001', 'c3333333-3333-3333-3333-333333333333', 'Optik: Lensa dan Cermin', 'optik-lensa-dan-cermin', 'Memahami cara kerja lensa dan cermin: pembiasan, pemantulan, dan penerapannya dari kacamata hingga teleskop.', 'id', 5, 'Madevi', v_owner, 'MEMBER', 'DRAFT', 'DEVELOPED_BY', v_owner, v_owner),
    (v_a5, 'SCH-SMP-SEJ4-001', 'd4444444-4444-4444-4444-444444444444', 'IPS Kelas 8: Kolonialisme dan Imperialisme', 'ips-kelas-8-kolonialisme-imperialisme', 'Materi IPS kelas 8: pengertian kolonialisme dan imperialisme, latar belakang kedatangan bangsa Eropa, serta dampaknya bagi Indonesia.', 'id', 7, 'Madevi', v_owner, 'MEMBER', 'DRAFT', 'DEVELOPED_BY', v_owner, v_owner),
    (v_a6, 'SCH-SD-BIN9-001', 'd3333333-3333-3333-3333-333333333333', 'Bahasa Indonesia Kelas 6: Menulis Surat Resmi', 'bahasa-indonesia-kelas-6-surat-resmi', 'Belajar menulis surat resmi: bagian-bagian surat, bahasa yang baku, contoh lengkap, dan latihan.', 'id', 5, 'Madevi', v_owner, 'MEMBER', 'DRAFT', 'DEVELOPED_BY', v_owner, v_owner)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
    (gen_random_uuid(), v_a1, 'HEADING', 1, jsonb_build_object('text', $$Masalah: Butuh Desain Bagus, Tapi Bukan Desainer$$)),
    (gen_random_uuid(), v_a1, 'PARAGRAPH', 2, jsonb_build_object('text', $$Banyak kebutuhan sehari-hari menuntut desain yang rapi: poster acara RT, slide presentasi kerja, thumbnail YouTube, sampai undangan digital. Menyewa desainer tidak selalu mungkin, dan software desain profesional seperti Photoshop punya kurva belajar yang curam. Canva hadir sebagai jalan tengah: alat desain berbasis web yang bisa dipakai siapa saja, gratis untuk kebutuhan dasar, dan hasilnya terlihat profesional.$$)),
    (gen_random_uuid(), v_a1, 'HEADING', 3, jsonb_build_object('text', $$Penjelasan: Apa Itu Canva$$)),
    (gen_random_uuid(), v_a1, 'PARAGRAPH', 4, jsonb_build_object('text', $$Canva adalah platform desain grafis online dengan sistem drag-and-drop. Alih-alih menggambar dari nol, pengguna memilih dari ribuan template siap pakai lalu mengganti teks, warna, dan gambarnya. Canva berjalan di browser (HP maupun laptop) sehingga tidak perlu instalasi berat. Versi gratis sudah mencakup sebagian besar kebutuhan; versi berbayar (Canva Pro) membuka stok foto premium, penghapus latar, dan kit merek.$$)),
    (gen_random_uuid(), v_a1, 'HEADING', 5, jsonb_build_object('text', $$Persiapan: Alat yang Dibutuhkan$$)),
    (gen_random_uuid(), v_a1, 'LIST', 6, jsonb_build_object('items', $$["Akun Canva gratis (daftar dengan email atau Google)", "Browser modern (Chrome/Edge/Firefox) atau aplikasi Canva di HP", "Koneksi internet yang stabil", "Materi konten: teks, logo, dan foto yang akan dipakai"]$$)),
    (gen_random_uuid(), v_a1, 'HEADING', 7, jsonb_build_object('text', $$Langkah: Membuat Desain Pertama$$)),
    (gen_random_uuid(), v_a1, 'LIST', 8, jsonb_build_object('items', $$["Tentukan ukuran kanvas: pilih template sesuai kebutuhan (misalnya Poster A4, Presentasi 16:9, atau Postingan Instagram).", "Pilih template yang mendekati selera, lalu ganti teksnya dengan kontenmu sendiri.", "Ganti warna sesuai identitas: gunakan maksimal 2-3 warna utama agar tidak ramai.", "Tambahkan gambar dari stok gratis Canva atau unggah fotomu sendiri.", "Atur hierarki teks: judul besar dan tebal, isi kecil dan ringkas. Satu pesan utama per desain.", "Unduh sebagai PNG untuk media sosial atau PDF untuk cetak."]$$)),
    (gen_random_uuid(), v_a1, 'HEADING', 9, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$)),
    (gen_random_uuid(), v_a1, 'PARAGRAPH', 10, jsonb_build_object('text', $$Kesalahan paling umum adalah memakai terlalu banyak font, warna, dan elemen sekaligus sehingga desain terlihat berantakan. Aturannya sederhana: maksimal dua jenis font, tiga warna, dan beri ruang kosong yang cukup. Risiko lain: memakai foto atau ikon berlisensi tanpa izin untuk keperluan komersial. Periksa lisensi setiap aset: elemen bertanda mahkota (Pro) tidak boleh dipakai komersial di akun gratis. Untuk karya klien, pastikan memakai aset bebas lisensi atau berlangganan Pro.$$)),
    (gen_random_uuid(), v_a1, 'HEADING', 11, jsonb_build_object('text', $$Pemeriksaan Hasil$$)),
    (gen_random_uuid(), v_a1, 'PARAGRAPH', 12, jsonb_build_object('text', $$Desain yang baik lolos tiga uji: pesan terbaca dalam 3 detik, tampilan rapi di layar HP, dan tidak ada typo. Minta satu orang lain melihat desainmu sebelum dipublikasikan; mata segar menangkap kesalahan yang luput dari pembuatnya. Jika tiga uji ini lolos, desainmu siap dipakai.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
    (gen_random_uuid(), v_a2, 'HEADING', 1, jsonb_build_object('text', $$Masalah: Hipertensi, Si Pembunuh Senyap$$)),
    (gen_random_uuid(), v_a2, 'PARAGRAPH', 2, jsonb_build_object('text', $$Tekanan darah tinggi (hipertensi) sering tidak bergejala sampai menimbulkan komplikasi serius seperti stroke, serangan jantung, atau gagal ginjal. Banyak orang baru tahu setelah memeriksakan diri secara kebetulan. Kabar baiknya: sebagian besar hipertensi dapat dikendalikan, dan gaya hidup adalah fondasi pengendaliannya — sebelum dan sesudah obat diresepkan dokter.$$)),
    (gen_random_uuid(), v_a2, 'HEADING', 3, jsonb_build_object('text', $$Penjelasan: Angka Tekanan Darah$$)),
    (gen_random_uuid(), v_a2, 'PARAGRAPH', 4, jsonb_build_object('text', $$Tekanan darah ditulis sebagai dua angka, misalnya 120/80 mmHg. Angka atas (sistolik) adalah tekanan saat jantung memompa; angka bawah (diastolik) saat jantung beristirahat. Secara umum, tekanan di bawah 120/80 dianggap normal, 120-139/80-89 masuk pra-hipertensi, dan 140/90 atau lebih masuk kategori hipertensi menurut banyak pedoman. Diagnosis resmi hanya bisa ditegakkan dokter berdasarkan pengukuran berulang, bukan sekali ukur.$$)),
    (gen_random_uuid(), v_a2, 'HEADING', 5, jsonb_build_object('text', $$Faktor Risiko yang Bisa Diubah$$)),
    (gen_random_uuid(), v_a2, 'LIST', 6, jsonb_build_object('items', $$["Kelebihan garam: konsumsi garam berlebih menaikkan tekanan darah.", "Kelebihan berat badan dan kurang aktivitas fisik.", "Merokok dan konsumsi alkohol berlebih.", "Stres kronis dan kurang tidur.", "Faktor yang tidak bisa diubah: usia, riwayat keluarga, dan kondisi medis tertentu."]$$)),
    (gen_random_uuid(), v_a2, 'HEADING', 7, jsonb_build_object('text', $$Langkah: Perubahan Gaya Hidup$$)),
    (gen_random_uuid(), v_a2, 'LIST', 8, jsonb_build_object('items', $$["Kurangi garam: batasi sekitar satu sendok teh per hari; kurangi makanan olahan, mi instan, dan camilan asin.", "Perbanyak sayur, buah, dan biji-bijian; pola makan seperti DASH terbukti membantu.", "Bergerak 30 menit sehari: jalan cepat, bersepeda, atau berenang, minimal 5 hari seminggu.", "Turunkan berat badan bila berlebih: tiap kilogram yang turun membantu menurunkan tekanan.", "Berhenti merokok dan batasi alkohol; kelola stres dengan tidur cukup dan relaksasi."]$$)),
    (gen_random_uuid(), v_a2, 'HEADING', 9, jsonb_build_object('text', $$Risiko: Jangan Mengandalkan Obat Herbal Saja$$)),
    (gen_random_uuid(), v_a2, 'PARAGRAPH', 10, jsonb_build_object('text', $$Banyak klaim herbal "penurun darah tinggi" beredar tanpa bukti kuat. Berhenti minum obat resep dokter lalu menggantinya dengan ramuan adalah keputusan berbahaya yang bisa berujung stroke. Suplemen dan herbal pun bisa berinteraksi dengan obat. Selalu konsultasikan ke dokter sebelum menambah atau menghentikan pengobatan apa pun.$$)),
    (gen_random_uuid(), v_a2, 'HEADING', 11, jsonb_build_object('text', $$Kapan Harus ke Dokter$$)),
    (gen_random_uuid(), v_a2, 'PARAGRAPH', 12, jsonb_build_object('text', $$Segera ke dokter atau IGD bila tekanan darah sangat tinggi disertai nyeri dada, sesak napas, sakit kepala hebat, gangguan penglihatan, atau mati rasa sebelah tubuh. Untuk pemantauan rutin, ukur tekanan darah di rumah dengan alat yang terkalibrasi dan catat hasilnya untuk dibawa saat kontrol. Artikel ini bersifat informasi umum dan bukan pengganti nasihat medis profesional — konsultasikan kondisimu dengan dokter.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
    (gen_random_uuid(), v_a3, 'HEADING', 1, jsonb_build_object('text', $$Siapa Suku Batak?$$)),
    (gen_random_uuid(), v_a3, 'PARAGRAPH', 2, jsonb_build_object('text', $$Suku Batak adalah kelompok etnis besar yang mendiami kawasan Sumatera Utara, terutama di sekitar Danau Toba. Istilah "Batak" sebenarnya payung bagi beberapa sub-etnis: Batak Toba, Karo, Simalungun, Pakpak, Angkola, dan Mandailing — masing-masing dengan bahasa dan adat yang khas, namun berbagi akar budaya yang sama. Populasinya jutaan jiwa, tersebar di seluruh Indonesia dan dunia lewat tradisi merantau.$$)),
    (gen_random_uuid(), v_a3, 'HEADING', 3, jsonb_build_object('text', $$Dalihan Na Tolu: Tiga Tungku Kehidupan$$)),
    (gen_random_uuid(), v_a3, 'PARAGRAPH', 4, jsonb_build_object('text', $$Falsafah inti masyarakat Batak adalah Dalihan Na Tolu — "tiga tungku" — yang mengatur hubungan kekerabatan dalam tiga peran: hula-hula (pihak pemberi istri, dihormati), dongan tubu (semarga, saudara sekandung marga, diajak berembuk), dan boru (pihak penerima istri, dilindungi dan dibantu). Ketiga unsur ini harus seimbang seperti tungku berkaki tiga; pincang satu, goyang semuanya. Falsafah ini masih hidup dalam pesta adat, musyawarah keluarga, hingga cara orang Batak menyapa.$$)),
    (gen_random_uuid(), v_a3, 'HEADING', 5, jsonb_build_object('text', $$Marga: Identitas yang Diwariskan$$)),
    (gen_random_uuid(), v_a3, 'PARAGRAPH', 6, jsonb_build_object('text', $$Setiap orang Batak mewarisi marga dari ayahnya (sistem patrilineal). Marga bukan sekadar nama belakang: ia menentukan siapa saudara, siapa calon besan, dan kepada siapa adat tertentu berlaku. Ada ratusan marga seperti Siregar, Nasution, Simbolon, dan Ginting. Aturan adat melarang pernikahan semarga, dan dalam perkenalan, menanyakan marga adalah cara cepat menemukan hubungan kekerabatan.$$)),
    (gen_random_uuid(), v_a3, 'HEADING', 7, jsonb_build_object('text', $$Adat, Ulos, dan Rumah Bolon$$)),
    (gen_random_uuid(), v_a3, 'PARAGRAPH', 8, jsonb_build_object('text', $$Upacara adat Batak — pernikahan, kelahiran, hingga kematian (saur matua) — terkenal meriah dan sarat makna. Kain ulos, tenunan khas dengan motif geometris, diberikan sebagai simbol restu dan kehangatan dalam setiap tahapan hidup. Rumah Bolon, rumah adat berbentuk perahu dengan atap ijuk menjulang, dahulu dihuni banyak keluarga besar sekaligus dan kini menjadi ikon wisata budaya di tepi Danau Toba.$$)),
    (gen_random_uuid(), v_a3, 'HEADING', 9, jsonb_build_object('text', $$Warisan untuk Indonesia$$)),
    (gen_random_uuid(), v_a3, 'PARAGRAPH', 10, jsonb_build_object('text', $$Orang Batak dikenal ulet dalam pendidikan dan perantauan — banyak tokoh nasional, pengusaha, dan seniman berasal dari tanah Batak. Musik (gondang), kuliner (arsik, saksang), dan semangat "tutur" yang hangat memperkaya kebudayaan Indonesia. Di era modern, Dalihan Na Tolu tetap relevan sebagai pelajaran tentang keseimbangan relasi: menghormati, bermusyawarah, dan melindungi — tiga tungku yang menopang kehidupan bersama.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
    (gen_random_uuid(), v_a4, 'HEADING', 1, jsonb_build_object('text', $$Dua Perilaku Cahaya$$)),
    (gen_random_uuid(), v_a4, 'PARAGRAPH', 2, jsonb_build_object('text', $$Optik adalah cabang fisika yang mempelajari cahaya dan interaksinya dengan materi. Dua perilaku cahaya menjadi fondasinya: pemantulan (refleksi) — cahaya memantul saat mengenai permukaan — dan pembiasan (refraksi) — cahaya membelok saat berpindah medium, misalnya dari udara ke kaca. Dari dua perilaku inilah lahir cermin dan lensa, dua alat optik paling berpengaruh dalam sejarah manusia.$$)),
    (gen_random_uuid(), v_a4, 'HEADING', 3, jsonb_build_object('text', $$Cermin: Bermain dengan Pantulan$$)),
    (gen_random_uuid(), v_a4, 'PARAGRAPH', 4, jsonb_build_object('text', $$Cermin datar memantulkan cahaya dengan sudut pantul sama dengan sudut datang, menghasilkan bayangan maya yang sama besar. Cermin cekung mengumpulkan cahaya ke satu titik fokus — dipakai pada lampu senter dan teleskop reflektor. Cermin cembung menyebarkan cahaya sehingga pandangan lebih luas — dipakai pada kaca spion dan tikungan jalan. Sifat-sifat ini dirumuskan dalam hukum pemantulan yang sederhana namun presisi.$$)),
    (gen_random_uuid(), v_a4, 'HEADING', 5, jsonb_build_object('text', $$Lensa: Membelokkan Cahaya$$)),
    (gen_random_uuid(), v_a4, 'PARAGRAPH', 6, jsonb_build_object('text', $$Lensa bekerja lewat pembiasan. Lensa cembung (konveks) memusatkan cahaya — dipakai pada kacamata rabun dekat, kaca pembesar, dan kamera. Lensa cekung (konkaf) menyebarkan cahaya — dipakai pada kacamata rabun jauh. Kekuatan lensa diukur dalam dioptri; semakin besar angkanya, semakin kuat pembelokannya. Kombinasi beberapa lensa dalam satu tabung memungkinkan mikroskop dan teleskop melihat hal yang tak terlihat mata telanjang.$$)),
    (gen_random_uuid(), v_a4, 'HEADING', 7, jsonb_build_object('text', $$Dari Kacamata hingga Teleskop$$)),
    (gen_random_uuid(), v_a4, 'PARAGRAPH', 8, jsonb_build_object('text', $$Kacamata, ditemukan sekitar abad ke-13, adalah penerapan lensa paling personal: mengoreksi kelainan refraksi mata jutaan manusia. Mikroskop membuka dunia mikroba dan sel; teleskop membuka jagat raya. Kamera modern, proyektor, hingga serat optik yang membawa internet — semuanya berdiri di atas prinsip optik yang sama.$$)),
    (gen_random_uuid(), v_a4, 'HEADING', 9, jsonb_build_object('text', $$Coba Sendiri$$)),
    (gen_random_uuid(), v_a4, 'PARAGRAPH', 10, jsonb_build_object('text', $$Pegang sendok makan menghadapmu: sisi cekung memperkecil wajahmu seperti cermin cembung mini, sisi cembung memperbesarnya. Teteskan air di atas tulisan kecil: tetesan air bertindak sebagai lensa cembung dan memperbesar huruf. Dua percobaan dapur ini membuktikan bahwa optik bukan teori jauh — ia bekerja di genggamanmu.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
    (gen_random_uuid(), v_a5, 'HEADING', 1, jsonb_build_object('text', $$Tujuan Pembelajaran$$)),
    (gen_random_uuid(), v_a5, 'LIST', 2, jsonb_build_object('items', $$["Menjelaskan pengertian kolonialisme dan imperialisme.", "Mengidentifikasi latar belakang kedatangan bangsa Eropa ke Indonesia.", "Menganalisis dampak kolonialisme bagi bangsa Indonesia."]$$)),
    (gen_random_uuid(), v_a5, 'HEADING', 3, jsonb_build_object('text', $$Pengertian Kolonialisme dan Imperialisme$$)),
    (gen_random_uuid(), v_a5, 'PARAGRAPH', 4, jsonb_build_object('text', $$Kolonialisme berasal dari kata colonia (Latin) yang berarti pemukiman: penguasaan suatu wilayah oleh negara asing untuk dijadikan daerah jajahan. Imperialisme berasal dari imperium (kekaisaran): perluasan kekuasaan suatu negara atas negara lain, baik secara langsung (teritorial) maupun tidak langsung (pengaruh ekonomi-politik). Sederhananya: kolonialisme menekankan penguasaan wilayah, imperialisme menekankan penguasaan kekuasaan — keduanya berjalan beriringan dalam sejarah penjajahan Indonesia.$$)),
    (gen_random_uuid(), v_a5, 'HEADING', 5, jsonb_build_object('text', $$Latar Belakang Kedatangan Bangsa Eropa$$)),
    (gen_random_uuid(), v_a5, 'LIST', 6, jsonb_build_object('items', $$["Motif 3G: Gold (kekayaan/rempah), Glory (kejayaan), Gospel (penyebaran agama).", "Revolusi ilmu pengetahuan: kompas, peta, dan kapal layar membuat pelayaran samudra mungkin.", "Jatuhnya Konstantinopel (1453) ke tangan Turki Utsmani menutup jalur dagang rempah lewat darat, mendorong Eropa mencari jalur laut baru.", "Bangsa Portugis tiba lebih dulu (1511 menguasai Malaka), disusul Spanyol, Belanda, dan Inggris."]$$)),
    (gen_random_uuid(), v_a5, 'HEADING', 7, jsonb_build_object('text', $$Penjajahan Belanda di Indonesia$$)),
    (gen_random_uuid(), v_a5, 'PARAGRAPH', 8, jsonb_build_object('text', $$Belanda menjajah Indonesia sekitar 350 tahun melalui beberapa tahap: VOC (1602-1799) sebagai perusahaan dagang bersenjata dengan hak monopoli; pemerintahan Hindia Belanda dengan sistem tanam paksa (cultuurstelsel, 1830) yang memaksa rakyat menanam komoditas ekspor; hingga politik etis awal abad ke-20 yang ironisnya melahirkan kaum terpelajar pribumi — bibit pergerakan nasional. Perlawanan rakyat tidak pernah padam: dari Pattimura, Diponegoro, Cut Nyak Dien, hingga Teuku Umar.$$)),
    (gen_random_uuid(), v_a5, 'HEADING', 9, jsonb_build_object('text', $$Dampak Kolonialisme$$)),
    (gen_random_uuid(), v_a5, 'LIST', 10, jsonb_build_object('items', $$["Bidang politik: raja-raja Nusantara kehilangan kedaulatan; wilayah dipecah belah.", "Bidang ekonomi: kekayaan alam dikuras; rakyat miskin akibat pajak dan kerja paksa.", "Bidang sosial-budaya: stratifikasi sosial (Eropa, Timur Asing, Pribumi); masuknya budaya dan agama baru.", "Dampak positif yang tak disengaja: infrastruktur (jalan, rel kereta), pendidikan modern, dan persatuan bahasa Indonesia."]$$)),
    (gen_random_uuid(), v_a5, 'HEADING', 11, jsonb_build_object('text', $$Latihan$$)),
    (gen_random_uuid(), v_a5, 'LIST', 12, jsonb_build_object('items', $$["Jelaskan perbedaan kolonialisme dan imperialisme dengan contohnya!", "Sebutkan tiga faktor pendorong bangsa Eropa datang ke Indonesia!", "Mengapa politik etis justru melahirkan pergerakan nasional? Jelaskan!", "Kunci: (1) Kolonialisme = penguasaan wilayah jajahan; imperialisme = perluasan kekuasaan/kekaisaran. (2) 3G, jatuhnya Konstantinopel 1453, kemajuan pelayaran. (3) Pendidikan barat melahirkan kaum terpelajar yang sadar akan penindasan dan menuntut kemerdekaan."]$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
    (gen_random_uuid(), v_a6, 'HEADING', 1, jsonb_build_object('text', $$Tujuan Pembelajaran$$)),
    (gen_random_uuid(), v_a6, 'LIST', 2, jsonb_build_object('items', $$["Menyebutkan bagian-bagian surat resmi.", "Menggunakan bahasa yang baku dan sopan dalam surat resmi.", "Menulis surat resmi sederhana dengan benar."]$$)),
    (gen_random_uuid(), v_a6, 'HEADING', 3, jsonb_build_object('text', $$Apa Itu Surat Resmi?$$)),
    (gen_random_uuid(), v_a6, 'PARAGRAPH', 4, jsonb_build_object('text', $$Surat resmi adalah surat yang digunakan untuk keperluan kedinasan atau formal, misalnya surat dari sekolah kepada orang tua, surat izin, atau surat undangan rapat. Berbeda dengan surat pribadi yang bahasanya santai, surat resmi memakai bahasa baku, sopan, dan mengikuti aturan penulisan yang baku. Tujuannya agar pesan tersampaikan jelas dan terlihat profesional.$$)),
    (gen_random_uuid(), v_a6, 'HEADING', 5, jsonb_build_object('text', $$Bagian-bagian Surat Resmi$$)),
    (gen_random_uuid(), v_a6, 'LIST', 6, jsonb_build_object('items', $$["Kop surat: nama dan alamat instansi di bagian atas.", "Nomor, lampiran, dan perihal surat.", "Tanggal surat.", "Alamat tujuan surat.", "Salam pembuka: 'Dengan hormat,'.", "Isi surat: pembuka, inti pesan, dan penutup.", "Salam penutup: 'Hormat kami,' atau 'Wassalamu'alaikum wr. wb.' bila sesuai.", "Tanda tangan, nama terang, dan jabatan pengirim.", "Tembusan bila diperlukan."]$$)),
    (gen_random_uuid(), v_a6, 'HEADING', 7, jsonb_build_object('text', $$Bahasa Surat Resmi$$)),
    (gen_random_uuid(), v_a6, 'PARAGRAPH', 8, jsonb_build_object('text', $$Gunakan kata baku: "kepada" bukan "kpd", "yang terhormat" bukan "yth" (singkatan hanya untuk ruang sempit). Hindari bahasa gaul dan singkatan tidak resmi. Kalimat harus jelas dan tidak bertele-tele. Contoh kalimat pembuka yang baik: "Sehubungan dengan akan diadakannya lomba kebersihan kelas, kami mengundang Bapak/Ibu untuk hadir pada..."$$)),
    (gen_random_uuid(), v_a6, 'HEADING', 9, jsonb_build_object('text', $$Contoh Surat Izin$$)),
